SELECT p.party_id AS partyId, p.order_id AS orderId, p.party_role AS partyRole, p.row_version AS rowVersion FROM vso_order_party p WHERE p.row_valid = 1 AND p.user_id = #{accountId} AND p.order_id IN
#{orderId}
AND p.party_role IN
#{role}
ORDER BY p.order_id, p.party_role, p.party_id

SELECT r.delivery_record_id AS deliveryRecordId, r.order_id AS orderId, r.delivery_status AS deliveryStatus, r.actual_delivery_time AS actualDeliveryTime, r.vehicle_vin AS vehicleVin, r.row_version AS rowVersion FROM vso_delivery_record r WHERE r.row_valid = 1 AND r.order_id IN
#{orderId}
ORDER BY r.order_id, r.delivery_record_id
